const RESERVED =
	/^(?:con|prn|aux|nul|com[0-9¹²³]|lpt[0-9¹²³])$/i;

export function safeWindowsFileName(name: string): string {
	return RESERVED.test(name) ? `_${name}` : name;
}

import { expect, test } from "bun:test";
import { safeWindowsFileName } from "./platform.js";

const RESERVED = [
	"con",
	"prn",
	"aux",
	"nul",
	...Array.from({ length: 10 }, (_, i) => `com${i}`),
	...Array.from({ length: 10 }, (_, i) => `lpt${i}`),
	"com¹",
	"com²",
	"com³",
	"lpt¹",
	"lpt²",
	"lpt³",
];

test("renames a reserved device name", () => {
	expect(safeWindowsFileName("con")).toBe("_con");
});

test("renames every reserved Windows device name", () => {
	for (const name of RESERVED) {
		expect(safeWindowsFileName(name)).toBe(`_${name}`);
		expect(safeWindowsFileName(name.toUpperCase())).toBe(`_${name.toUpperCase()}`);
	}
});

test("leaves non-reserved names unchanged", () => {
	expect(safeWindowsFileName("readme")).toBe("readme");
	expect(safeWindowsFileName("com10")).toBe("com10");
	expect(safeWindowsFileName("lpt10")).toBe("lpt10");
	expect(safeWindowsFileName("_con")).toBe("_con");
});

test.skipIf(process.platform !== "win32")(
	"creates the replacement on Windows",
	() => {
		throw new Error("Only a Windows host can observe this.");
	},
);

